<?php
namespace App\Http\Controllers;
use App\Models\{User,Post,Category,Comment}; use Illuminate\Http\Request;
class AdminController extends Controller { public function index(){return view('admin.index',['stats'=>['users'=>User::count(),'posts'=>Post::count(),'pending'=>Post::where('status','pending')->count(),'comments'=>Comment::count()]]);} public function posts(Request $r){$posts=Post::with(['user','category'])->when($r->status,fn($q,$v)=>$q->where('status',$v))->latest()->paginate(20);return view('admin.posts',compact('posts'));} public function approve(Post $post){$post->update(['status'=>'approved','published_at'=>now(),'rejection_reason'=>null]);return back();} public function reject(Request $r,Post $post){$post->update(['status'=>'rejected','rejection_reason'=>$r->input('reason')]);return back();} public function categories(){return view('admin.categories',['categories'=>Category::orderBy('sort_order')->get()]);} public function storeCategory(Request $r){$d=$r->validate(['name'=>'required|max:80','description'=>'nullable|max:500']);Category::create($d+['slug'=>\Illuminate\Support\Str::slug($d['name'])]);return back();} }
